<section class="container py-4"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-3 mb-4"><div><h1 class="h2 fw-bold mb-1">Lịch khám được phân công</h1><p class="text-secondary mb-0">Bác sĩ chỉ xem các lịch thuộc ca làm việc của mình.</p></div><a class="btn btn-outline-primary" href="<?= e(url('doctor.schedules')) ?>">Đăng ký / quản lý ca làm việc</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Mã lịch</th><th>Bệnh nhân</th><th>Dịch vụ</th><th>Ngày</th><th>Giờ</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach ($appointments as $a): ?><tr><td>#<?= (int)$a['MaLH'] ?></td><td><?= e($a['TenBenhNhan']) ?><br><small class="text-secondary"><?= e($a['SDT']) ?></small></td><td><?= e($a['TenDV']) ?></td><td><?= e($a['NgayKham']) ?></td><td><?= e(substr($a['GioBatDau'],0,5)) ?>–<?= e(substr($a['GioKetThuc'],0,5)) ?></td><td><?= status_badge($a['TrangThai']) ?></td><td><form method="post" action="<?= e(url('doctor.visit.start')) ?>"><?= csrf_field() ?><input type="hidden" name="MaLH" value="<?= (int)$a['MaLH'] ?>"><button class="btn btn-sm btn-primary" <?= $a['TrangThai']==='DA_HUY'?'disabled':'' ?>>Tiếp nhận / mở lần khám</button></form></td></tr><?php endforeach; ?><?php if (!$appointments): ?><tr><td colspan="7" class="text-center text-secondary py-4">Chưa có lịch được phân công.</td></tr><?php endif; ?></tbody></table></div></div></section>
